291	async function initWorkspaceUnlocked(
292	  paths: ContinuityPaths,
293	  input: CurrentFrameInput,
294	  options: { now?: Clock } = {},
295	): Promise<CurrentFrame> {
296	  if (await exists(paths.currentPath)) throw new Error(`Workspace ${paths.workspace.key} is already initialized`);
297	
298	  const now = (options.now ?? nowIso)();
299	  const frameInput = ensureCurrentInput(input);
300	  const current: CurrentFrame = {
301	    version: CURRENT_SCHEMA_VERSION,
302	    updated_at: now,
303	    workspace: paths.workspace,
304	    ...frameInput,
305	    active_task: frameInput.active_task ?? null,
306	  };
307	
308	  let index: IndexFile;
309	  const existingIndex = await readIndex(paths);
310	  if (existingIndex.kind === "ok") {
311	    index = existingIndex.value;
312	  } else if (existingIndex.kind === "missing") {
313	    index = { version: INDEX_SCHEMA_VERSION, updated_at: now, workspaces: [] };
314	  } else {
315	    throw new Error(`Cannot initialize with malformed index: ${existingIndex.message}`);
316	  }
317	
318	  const existingWorkspace = index.workspaces.find((item) => item.key === paths.workspace.key);
319	  const workspaceIndexEntry = {
320	    key: paths.workspace.key,
321	    kind: paths.workspace.kind,
322	    root: paths.workspace.root,
323	    label: paths.workspace.label ?? paths.workspace.key,
324	    created_at: existingWorkspace?.created_at ?? now,
325	    updated_at: now,
326	  };
327	
328	  index = {
329	    version: INDEX_SCHEMA_VERSION,
330	    updated_at: now,
331	    workspaces: existingWorkspace
332	      ? index.workspaces.map((item) => (item.key === paths.workspace.key ? workspaceIndexEntry : item))
333	      : [...index.workspaces, workspaceIndexEntry],
334	  };
335	
336	  await mkdir(paths.workspaceDir, { recursive: true });
337	  await writeJsonAtomic(paths.indexPath, index);
338	  await writeJsonAtomic(paths.currentPath, current);
339	  await writeFile(paths.eventsPath, "", { encoding: "utf8", flag: "a" });
340	  return current;
341	}
