327	export async function checkpointActiveTask(
328	  input: CheckpointActiveTaskInput,
329	): Promise<CheckpointActiveTaskOutput> {
330	  const checkpointId = input.checkpointId.trim();
331	  if (checkpointId.length === 0 || checkpointId.length > 200) {
332	    throw new ContinuityServiceError("VALIDATION_ERROR", "checkpointId must contain between 1 and 200 characters");
333	  }
334	  const summary = input.task.state === "clear" ? input.task.outcome.trim() : input.task.summary.trim();
335	  if (summary.length === 0 || summary.length > MAX_ACTIVE_TASK_TEXT_CHARS) {
336	    throw new ContinuityServiceError(
337	      "VALIDATION_ERROR",
338	      `task summary must contain between 1 and ${MAX_ACTIVE_TASK_TEXT_CHARS} characters`,
339	    );
340	  }
341	  if (input.task.state !== "clear") {
342	    const nextStep = input.task.nextStep.trim();
343	    if (nextStep.length === 0 || nextStep.length > MAX_ACTIVE_TASK_TEXT_CHARS) {
344	      throw new ContinuityServiceError(
345	        "VALIDATION_ERROR",
346	        `task next step must contain between 1 and ${MAX_ACTIVE_TASK_TEXT_CHARS} characters`,
347	      );
348	    }
349	  }
350	  if ((input.task.details?.length ?? 0) > MAX_ACTIVE_TASK_DETAILS_CHARS) {
351	    throw new ContinuityServiceError(
352	      "VALIDATION_ERROR",
353	      `task details must contain at most ${MAX_ACTIVE_TASK_DETAILS_CHARS} characters`,
354	    );
355	  }
356	
357	  const paths = resolveBoundContinuityWorkspace(input);
358	  return withWorkspaceMutationLock(paths, async () => {
359	    const before = await readCurrent(paths);
360	    if (before.kind === "malformed") throw new ContinuityServiceError("CONTINUITY_MALFORMED", before.message);
361	
362	    const eventId = checkpointEventId(paths.workspace.key, checkpointId);
363	    const events = await readAllEvents(paths);
364	    if (events.kind === "malformed") throw new ContinuityServiceError("CONTINUITY_MALFORMED", events.message);
365	    const existing = events.kind === "ok" ? events.events.find((event) => event.id === eventId) : undefined;
366	    const details = checkpointDetails(input.task);
367	    if (existing && !checkpointEventMatches(existing, input.task, details)) {
368	      throw new ContinuityServiceError(
369	        "VALIDATION_ERROR",
370	        `checkpointId ${checkpointId} was already used for different task content`,
371	      );
372	    }
373	    if (input.task.state === "clear" && before.kind === "missing" && !existing) {
374	      throw new ContinuityServiceError("CONTINUITY_NOT_INITIALIZED", "Cannot clear an active task before Continuity exists");
375	    }
376	    if (input.task.state === "clear" && before.kind === "ok" && before.value.active_task === null && !existing) {
377	      throw new ContinuityServiceError("VALIDATION_ERROR", "No active task is available to clear");
378	    }
379	
380	    const priorTask = before.kind === "ok" ? before.value.active_task : null;
381	    const eventInput: EventInput = {
382	      type: input.task.state === "clear" ? "correction" : "next_action",
383	      status: "active",
384	      summary: input.task.state === "clear" ? input.task.outcome : input.task.summary,
385	      details,
386	      supersedes:
387	        input.task.state !== "clear" && priorTask && priorTask.event_id !== eventId ? [priorTask.event_id] : [],
388	      resolves: input.task.state === "clear" && priorTask ? [priorTask.event_id] : [],
389	      related_events: priorTask ? [priorTask.event_id] : [],
390	    };
391	    const event =
392	      existing ??
393	      (await recordEvent(paths, eventInput, {
394	        source: boundEventSource(input.binding, input.source),
395	        now: input.now,
396	        id: () => eventId,
397	      }));
398	
399	    const afterRecord = await readCurrent(paths);
400	    if (afterRecord.kind !== "ok") {
401	      throw new ContinuityServiceError("CONTINUITY_MALFORMED", afterRecord.message);
402	    }
403	    const desired: ActiveTask | null =
404	      input.task.state === "clear"
405	        ? null
406	        : activeTaskSchema.parse({
407	            event_id: event.id,
408	            recorded_at: event.effective_at ?? event.created_at,
409	            summary: input.task.summary,
410	            state: input.task.state,
411	            next_step: input.task.nextStep,
412	          });
413	    const taskChanged = JSON.stringify(afterRecord.value.active_task) !== JSON.stringify(desired);
414	    const nextInput = currentFrameInput(afterRecord.value);
415	    nextInput.active_task = desired;
416	    nextInput.next_actions = nextInput.next_actions.filter((item) => item.event_id !== event.id);
417	    const changed = taskChanged || nextInput.next_actions.length !== afterRecord.value.next_actions.length;
418	    const frame = changed
419	      ? await updateCurrent(paths, nextInput, { now: input.now })
420	      : afterRecord.value;
421	
422	    return {
423	      paths,
424	      workspace: paths.workspace,
425	      event,
426	      frame,
427	      rendered: renderContinuityFrame(frame),
428	      changed,
429	      binding: workContextBindingView(input.binding),
430	    };
431	  }, { now: input.now });
432	}
