164	async function readEventLog(paths: ContinuityPaths): Promise<ReadResult<ContinuityEvent[]>> {
165	  let text;
166	  try {
167	    text = await readFile(paths.eventsPath, "utf8");
168	  } catch (error) {
169	    if (isNodeError(error) && error.code === "ENOENT") {
170	      return { kind: "missing", path: paths.eventsPath, message: `${paths.eventsPath} does not exist` };
171	    }
172	    const message = error instanceof Error ? error.message : String(error);
173	    return { kind: "malformed", path: paths.eventsPath, message };
174	  }
175	
176	  const events: ContinuityEvent[] = [];
177	  const lines = text.split("\n").filter((line) => line.trim().length > 0);
178	  for (const [index, line] of lines.entries()) {
179	    let parsed;
180	    try {
181	      parsed = JSON.parse(line);
182	    } catch (error) {
183	      const message = error instanceof Error ? error.message : String(error);
184	      return { kind: "malformed", path: paths.eventsPath, message: `Malformed event JSON on line ${index + 1}: ${message}` };
185	    }
186	
187	    const validated = validateContinuityEvent(parsed);
188	    if (!validated.ok) {
189	      return { kind: "malformed", path: paths.eventsPath, message: `Invalid event on line ${index + 1}: ${validated.message}` };
190	    }
191	    events.push(validated.value);
192	  }
193	
194	  return { kind: "ok", value: events };
195	}
